import Foundation

extension SocialSupportGuides {
    static let aidOrganizations = DirectoryGuide(
        cardSummary: .init(ukrainian: "Їжа, ризик втрати житла, борги й соціальна консультація", german: "Essen, Wohnungsverlust, Schulden und Sozialberatung"),
        introduction: .init(ukrainian: "Недержавні служби допомагають у конкретній кризі, але не замінюють заяву до відповідального органу. Обирайте службу за найближчою потребою та регіоном.", german: "Hilfsorganisationen unterstützen bei konkreten Notlagen, ersetzen aber keinen Behördenantrag. Wählen Sie nach dringendem Bedarf und Region."),
        sections: [
            .init("today", "fork.knife", "Якщо сьогодні немає їжі чи речей першої потреби", "Wenn heute Essen oder Grundbedarf fehlt", "Зверніться до місцевої Caritas, Diakonie, Volkshilfe або Rotes Kreuz через офіційний перелік. Одразу скажіть, скільки дорослих і дітей потребують допомоги та чи вона потрібна сьогодні. Запитайте про продуктову допомогу, години видачі, умови й можливість соціальної консультації; наявність допомоги залежить від відділення.", "Örtliche Caritas, Diakonie, Volkshilfe oder Rotes Kreuz über die amtliche Übersicht suchen. Gleich Zahl der Erwachsenen und Kinder sowie Bedarf noch heute nennen. Nach Lebensmittelhilfe, Ausgabezeiten, Voraussetzungen und Sozialberatung fragen; das Angebot hängt von der Stelle ab.", source: aid),
            .init("housing-crisis", "house.lodge", "Якщо загрожує втрата житла", "Wenn Wohnungsverlust droht", "Не чекайте виселення: зберіть договір оренди, листи власника або суду й суму боргу. На офіційному порталі знайдіть службу вашої землі з профілактики виселення або екстреного житла, повідомте найближчу дату втрати житла й склад сім’ї. Попросіть план дій та письмове підтвердження звернення.", "Nicht bis zur Räumung warten: Mietvertrag, Schreiben von Vermieter oder Gericht und Rückstand bereithalten. Auf dem amtlichen Portal die Stelle im Bundesland für Delogierungsprävention oder Notunterkunft suchen, drohendes Datum und Haushalt nennen. Vorgehen und Eingangsbestätigung erfragen.", source: homelessness),
            .init("debt", "eurosign.circle", "Якщо накопичилися борги", "Wenn Schulden wachsen", "Запишіть кредиторів, суми, строки, доходи й обов’язкові витрати. У кожній землі є державновизнана безоплатна Schuldenberatung; домовтеся про зустріч до підписання нової позики або сумнівної угоди про погашення. Консультація допомагає скласти план, але сама не виплачує борги.", "Gläubiger, Beträge, Fristen, Einkommen und notwendige Ausgaben notieren. In jedem Bundesland gibt es staatlich anerkannte kostenlose Schuldenberatung; Termin vor neuem Kredit oder unklarer Zahlungsvereinbarung vereinbaren. Die Beratung hilft beim Plan, zahlt Schulden aber nicht selbst.", source: debt),
            .init("advice", "person.2", "Попросіть перевірити всі доступні варіанти", "Alle Hilfswege prüfen lassen", "У соціальній консультації коротко назвіть статус, землю, склад сім’ї, доходи та вже подані заяви. Попросіть розділити термінову допомогу, державні виплати й направлення до спеціалізованої служби. Візьміть тільки необхідні документи й запитайте, хто зберігатиме копії. Відповідь однієї організації не є рішенням про державну виплату.", "In der Sozialberatung Status, Bundesland, Haushalt, Einkommen und laufende Anträge knapp schildern. Um Trennung von Soforthilfe, staatlichen Leistungen und Überweisung an Fachstellen bitten. Nur nötige Dokumente mitbringen und nach Umgang mit Kopien fragen. Die Auskunft einer Organisation ist kein behördlicher Leistungsbescheid.", source: aid),
            .init("safe", "checkmark.shield", "Перевірте, з ким маєте справу", "Angebote sicher prüfen", "Звірте адресу й телефон на офіційному сайті організації. Не передавайте стороннім оригінал паспорта, доступ до банку або гроші за «гарантовану допомогу». Якщо просять підписати незрозуміле зобов’язання, візьміть копію і попросіть незалежну консультацію до підписання.", "Adresse und Telefonnummer auf der offiziellen Organisationsseite prüfen. Fremden weder Originalpass noch Bankzugang oder Geld für „garantierte Hilfe“ geben. Bei unklarem Vertrag Kopie mitnehmen und vor Unterschrift unabhängige Beratung suchen.", source: aid)
        ], sources: [aid, homelessness, debt]
    )
}
